// LeetCode 272 — the k values in a BST closest to a target, returned in ascending order.
// On a tie in distance, the smaller value wins.
public static class ClosestBstK {
    public static IList<int> KClosest(TreeNode root, double target, int k) {
        // 1. An in-order walk lists a BST's values in sorted order.
        var values = new List<int>();
        var stack = new Stack<TreeNode>();
        TreeNode cur = root;
        while (cur != null || stack.Count > 0) {
            while (cur != null) { stack.Push(cur); cur = cur.Left; }
            cur = stack.Pop();
            values.Add(cur.Value);
            cur = cur.Right;
        }
        if (k < 0 || k > values.Count) throw new ArgumentOutOfRangeException(nameof(k));
        // 2. The answer is a contiguous window of the sorted list. Start with everything and
        //    drop whichever END is farther from the target until k values remain.
        int lo = 0, hi = values.Count - 1;
        while (hi - lo + 1 > k) {
            double dl = Math.Abs(values[lo] - target), dh = Math.Abs(values[hi] - target);
            if (dl > dh) lo++;      // the small end is farther
            else hi--;              // the big end is farther, or a tie: keep the smaller value
        }
        return values.GetRange(lo, k);
    }
}
```

