        var root = new TreeNode(level[0].Value); var q = new Queue<TreeNode>(); q.Enqueue(root); int i = 1;
        while (q.Count > 0 && i < level.Length) {
            var n = q.Dequeue();
            if (i < level.Length && level[i] != null) { n.Left = new TreeNode(level[i].Value); q.Enqueue(n.Left); } i++;
            if (i < level.Length && level[i] != null) { n.Right = new TreeNode(level[i].Value); q.Enqueue(n.Right); } i++;
        }
        return root;
    }
