        var parts = new List<string>(); var q = new Queue<TreeNode>(); q.Enqueue(root);
        while (q.Count > 0) { var n = q.Dequeue(); if (n == null) { parts.Add("null"); continue; } parts.Add(n.Value.ToString()); q.Enqueue(n.Left); q.Enqueue(n.Right); }
        while (parts.Count > 0 && parts[parts.Count - 1] == "null") parts.RemoveAt(parts.Count - 1);
