public static class ClosestBstK {
    public static IList<int> KClosest(TreeNode root, double target, int k) {
        // 1. An in-order walk lists a BST's values in sorted order.
        var values = new List<int>();
        var stack = new Stack<TreeNode>();
        TreeNode cur = root;
        while (cur != null || stack.Count > 0) {
            while (cur != null) { stack.Push(cur); cur = cur.Left; }
