            cur = cur.Right;
        }
        if (k < 0 || k > values.Count) throw new ArgumentOutOfRangeException(nameof(k));
        // 2. The answer is a contiguous window of the sorted list. Start with everything and
        //    drop whichever END is farther from the target until k values remain.
        int lo = 0, hi = values.Count - 1;
        while (hi - lo + 1 > k) {
            double dl = Math.Abs(values[lo] - target), dh = Math.Abs(values[hi] - target);
            if (dl > dh) lo++;      // the small end is farther
            else hi--;              // the big end is farther, or a tie: keep the smaller value
        }
        return values.GetRange(lo, k);
    }
}
```

## Likely follow-up questions

**Q: Why a window?**

If a value is among the k closest, every value between it and the target is closer, so it is in too.

**Q: Complexity?**

O(n) time and memory.

**Q: Faster?**

Two stacks — predecessors and successors of the target — then merge k steps: O(h + k).

**Q: Shared state?**

Read-only tree.

**Q: A huge BST and small k.**

The two-stack version never touches the rest of the tree.

**Q: Related?**

Find K Closest Elements (658) — the same window idea on an array, with binary search for the start.

